const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let meta,offset=0,lastQuery='',generation=0,returnFocus=null;
const form=$('#search-form');
function drawer(id,open){$('#'+id).hidden=!open;document.body.classList.toggle(id+'-open',open);if(id==='tools')$('#tools-toggle').setAttribute('aria-expanded',String(open));if(id==='nav')$('#nav-toggle').setAttribute('aria-expanded',String(open));}
$('#nav-toggle').onclick=()=>drawer('nav',$('#nav').hidden);
$('#tools-toggle').onclick=()=>{drawer('detail',false);drawer('tools',$('#tools').hidden);if(!$('#tools').hidden)$('#query').focus();};
$('#close-tools').onclick=()=>{drawer('tools',false);$('#tools-toggle').focus();};
$('#close-detail').onclick=()=>{drawer('detail',false);returnFocus?.focus();};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){drawer('tools',false);drawer('detail',false);drawer('nav',false);returnFocus?.focus();}});
$('#coverage-toggle').onclick=()=>{$('#coverage').hidden=!$('#coverage').hidden;drawer('nav',false);};
async function api(path){const r=await fetch(path);if(!r.ok)throw Error('Request failed ('+r.status+'). Try again.');return r.json();}
function showError(e){$('#error').hidden=false;$('#error').textContent=e.message;}
function chips(g){return Object.values(g.styles).flat().slice(0,6).map(s=>`<span class="chip">${esc(s)}</span>`).join('');}
function card(g){return `<button class="card" data-id="${esc(g.id)}"><span class="dimension ${g.styleStatus==='unclassified'?'unclassified':''}">${esc(g.styles.dimension.join(' + ')||'DIMENSION UNREVIEWED')}</span><h3>${esc(g.name)}</h3><div class="tags">${chips(g)||'<span class="chip">Style awaiting review</span>'}</div>${g.matchedConcepts?.length?`<p>Matched: ${g.matchedConcepts.map(esc).join(', ')}</p>`:''}<div class="bottom"><span>${g.ownership==='owned-snapshot'?'Owned snapshot':'Ownership unverified'}</span><span>${g.installation.present?(g.installation.folderExists===false?'Folder missing':g.installation.complete?'Installed':'Partial install'):'Not installed'}</span></div></button>`;}
function bindCards(){$$('#results [data-id]').forEach(b=>b.onclick=()=>{returnFocus=b;detail(b.dataset.id);});}
function $$(s){return [...document.querySelectorAll(s)];}
async function load(){const ticket=++generation;$('#error').hidden=true;const p=new URLSearchParams(new FormData(form));for(const [k,v]of [...p])if(!v)p.delete(k);p.set('offset',offset);p.set('limit','30');lastQuery=p.toString();try{const d=await api('/api/games?'+p);if(ticket!==generation)return;$('#result-count').textContent=d.total+(d.total===1?' reference':' references');$('#query-summary').textContent=d.query?`“${d.query}” · concept-expanded search`:'All matching references';$('#results').innerHTML=d.results.length?d.results.map(card).join(''):'<p>No matches. Try a broader phrase or clear filters.</p>';bindCards();$('#pagination').innerHTML=`${offset>0?'<button id="previous">Previous</button>':''}<span class="chip">${d.total?offset+1:0}–${Math.min(offset+30,d.total)} of ${d.total}</span>${offset+30<d.total?'<button id="next">Next 30</button>':''}`;if($('#previous'))$('#previous').onclick=()=>{offset=Math.max(0,offset-30);load();window.scrollTo(0,0);};if($('#next'))$('#next').onclick=()=>{offset+=30;load();window.scrollTo(0,0);};const url=new URL(location.href);url.search=p.toString();history.replaceState(null,'',url);}catch(e){showError(e);}}
form.onsubmit=e=>{e.preventDefault();offset=0;load();if(innerWidth<=800)drawer('tools',false);};
form.onreset=()=>setTimeout(()=>{offset=0;load();},0);
$$('[data-query]').forEach(b=>b.onclick=()=>{$('#query').value=b.dataset.query;offset=0;load();if(innerWidth<=800)drawer('tools',false);});
let debounce;$('#query').oninput=()=>{clearTimeout(debounce);debounce=setTimeout(()=>{offset=0;load();},250);};
form.querySelectorAll('select').forEach(s=>s.onchange=()=>{offset=0;load();});
async function detail(id){try{const {game:g}=await api('/api/games?id='+encodeURIComponent(id));drawer('tools',false);drawer('detail',true);$('#detail-content').innerHTML=`<div class="dimension">${esc(g.styleStatus)}</div><h1>${esc(g.name)}</h1><p>${esc(g.summary)}</p><div>${chips(g)}</div><p>${g.ownership==='owned-snapshot'?'Listed in the October 13 ownership snapshot.':'Ownership has not been verified.'} ${g.installation.present?(g.installation.folderExists===false?'Steam manifest exists, but the game folder is missing.':g.installation.complete?'Complete local installation manifest and game folder present.':'Local manifest indicates an incomplete installation.'):'No current local manifest.'}</p>${Object.entries(g.styles).map(([k,v])=>`<h3>${esc(k)}</h3><p>${v.length?v.map(esc).join(' · '):'Unknown — not classified'}</p>`).join('')}<h3>Evidence</h3>${g.evidence.map(e=>`<div class="evidence"><strong>${e.url?`<a href="${esc(e.url)}" target="_blank" rel="noopener">${esc(e.label)} ↗</a>`:esc(e.label)}</strong><p>${esc(e.status)}</p>${e.checkedAt?`<small>Checked ${esc(e.checkedAt.slice(0,10))}</small>`:''}${e.sha256?`<small>SHA-256 ${esc(e.sha256)}</small>`:''}</div>`).join('')}${g.researchNotes.length?'<h3>Prior research · not revalidated</h3>'+g.researchNotes.map(n=>`<p>${esc(n.text)}</p>`).join(''):''}${g.warnings.length?'<h3>Uncertainty</h3><p>'+g.warnings.map(esc).join(' ')+'</p>':''}<h3>Related visual directions</h3><button id="similar" class="primary">Find similar styles</button><p><a href="/api/games?id=${encodeURIComponent(id)}" target="_blank">Read JSON record ↗</a></p>`;$('#close-detail').focus();$('#similar').onclick=async()=>{try{const d=await api('/api/games?similar='+encodeURIComponent(id));$('#results').innerHTML=d.results.map(g=>card({...g,matchedConcepts:g.shared})).join('')||'<p>No classified style overlap yet.</p>';$('#result-count').textContent='Related references';$('#query-summary').textContent='Shared art attributes with '+g.name;$('#pagination').innerHTML='';bindCards();drawer('detail',false);window.scrollTo(0,0);}catch(e){showError(e);}};}catch(e){showError(e);}}
async function init(){try{meta=await api('/api/meta');$('#version').textContent='Snapshot '+meta.version.slice(0,8);$('#stats').textContent=`${meta.counts.entries} records · ${meta.counts.styleTagged} style-tagged · ${meta.counts.installedManifests} manifests`;for(const k of ['dimension','perspective','rendering'])for(const v of meta.facets[k])$('#'+k).add(new Option(v,v));const params=new URLSearchParams(location.search);for(const [k,v]of params)if(form.elements[k])form.elements[k].value=v;offset=Math.max(0,parseInt(params.get('offset'))||0);$('#coverage').innerHTML=`<h2>Inventory & evidence coverage</h2><p>${meta.counts.ownedSnapshot} historical owned entries · ${meta.counts.installedManifests} current manifests · ${meta.counts.completeInstallations} complete installations · ${meta.counts.installedOwnershipUnverified} installed entries without ownership proof · ${meta.counts.olderCorpusImported} older-corpus records imported.</p><ul>${meta.coverageGaps.map(g=>`<li>${esc(g)}</li>`).join('')}</ul><p>Hosted snapshot ${esc(meta.version)}. Reads work independently of the PC. Updated ${esc(meta.generatedAt)}.</p>`;await load();}catch(e){showError(e);$('#stats').textContent='Catalog unavailable';}}init();
